import json
import re
from collections import OrderedDict, defaultdict

SECTION_RE = re.compile(r"^\[(.+?)\]\s*$")
CHOICE_RE = re.compile(r"^\s*\d+\.\s*(.*?)\s*->\s*(\S+)\s*$")
DIALOGUE_RE = re.compile(r"^\s*([^:]+):\s*(.*?)(?:\s*->\s*(\S+)\s*)?$")


def _dot_escape(value: str) -> str:
    return value.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n")


def parse_script(text: str):
    sections = OrderedDict()
    current = None

    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line:
            continue
        m = SECTION_RE.match(line)
        if m:
            current = m.group(1).strip()
            if current in sections:
                raise ValueError(f"Duplicate section: {current}")
            sections[current] = []
            continue
        if current is None:
            raise ValueError(f"Content outside section: {line}")
        sections[current].append(line)

    nodes = []
    edges = []

    for node_id, lines in sections.items():
        if not lines:
            nodes.append({"id": node_id, "text": "", "speaker": "", "type": "line"})
            continue

        is_choice_block = all(CHOICE_RE.match(l) for l in lines)
        if is_choice_block:
            nodes.append({"id": node_id, "text": "", "speaker": "", "type": "choice"})
            for line in lines:
                m = CHOICE_RE.match(line)
                if not m:
                    raise ValueError(f"Invalid choice line in [{node_id}]: {line}")
                choice_text = m.group(1).strip()
                target = m.group(2).strip()
                edges.append({"from": node_id, "to": target, "text": choice_text})
            continue

        # Dialogue block
        entries = []
        target = None
        for line in lines:
            m = DIALOGUE_RE.match(line)
            if not m:
                raise ValueError(f"Invalid dialogue line in [{node_id}]: {line}")
            speaker = m.group(1).strip()
            text_part = m.group(2).strip()
            entry_target = m.group(3)
            entries.append((speaker, text_part))
            if entry_target:
                entry_target = entry_target.strip()
                if target is not None and entry_target != target:
                    raise ValueError(f"Multiple targets in [{node_id}]")
                target = entry_target

        if len(entries) == 1:
            speaker, text_part = entries[0]
        else:
            speakers = {s for s, _ in entries}
            if len(speakers) == 1:
                speaker = entries[0][0]
                text_part = "\n".join(t for _, t in entries)
            else:
                speaker = ""
                text_part = "\n".join(f"{s}: {t}" for s, t in entries)

        nodes.append({"id": node_id, "text": text_part, "speaker": speaker, "type": "line"})
        if target:
            edges.append({"from": node_id, "to": target, "text": ""})

    node_ids = {n["id"] for n in nodes}
    missing_targets = {e["to"] for e in edges if e["to"] not in node_ids}
    if missing_targets:
        if len(missing_targets) > 1:
            raise ValueError(f"Undefined targets: {sorted(missing_targets)}")
        missing_id = next(iter(missing_targets))
        nodes.append({"id": missing_id, "text": "", "speaker": "", "type": "line"})
        node_ids.add(missing_id)

    if nodes:
        start_id = nodes[0]["id"]
        adjacency = defaultdict(list)
        for edge in edges:
            adjacency[edge["from"]].append(edge["to"])

        seen = set()
        stack = [start_id]
        while stack:
            node = stack.pop()
            if node in seen:
                continue
            seen.add(node)
            for nxt in adjacency.get(node, []):
                if nxt in node_ids:
                    stack.append(nxt)

        unreachable = [nid for nid in node_ids if nid not in seen]
        if unreachable:
            raise ValueError(f"Unreachable nodes: {unreachable}")

    return {"nodes": nodes, "edges": edges}


def to_dot(graph) -> str:
    lines = ["digraph Dialogue {", "  rankdir=LR;"]

    for node in graph["nodes"]:
        label_parts = [node["id"]]
        if node["type"] == "line":
            if node["speaker"] or node["text"]:
                if node["speaker"]:
                    label_parts.append(f"{node['speaker']}: {node['text']}")
                else:
                    label_parts.append(node["text"])
        else:
            label_parts.append("choice")

        label = _dot_escape("\n".join(part for part in label_parts if part))
        shape = "box" if node["type"] == "line" else "diamond"
        lines.append(f"  \"{node['id']}\" [shape={shape}, label=\"{label}\"];" )

    for edge in graph["edges"]:
        if edge["text"]:
            label = _dot_escape(edge["text"])
            lines.append(f"  \"{edge['from']}\" -> \"{edge['to']}\" [label=\"{label}\"];" )
        else:
            lines.append(f"  \"{edge['from']}\" -> \"{edge['to']}\";")

    lines.append("}")
    return "\n".join(lines)


def main():
    with open("/app/script.txt", "r", encoding="utf-8") as f:
        text = f.read()

    graph = parse_script(text)

    with open("/app/dialogue.json", "w", encoding="utf-8") as f:
        json.dump(graph, f, indent=2, ensure_ascii=True)
        f.write("\n")

    dot = to_dot(graph)
    with open("/app/dialogue.dot", "w", encoding="utf-8") as f:
        f.write(dot)
        f.write("\n")


if __name__ == "__main__":
    main()
